script:
users = frappe.get_all(
    "Has Role",
    filters={
        "role": "Project User"
    },
    fields=["parent"],
    limit_page_length=0
)

user_names = [row.parent for row in users]

if not user_names:
    frappe.response["message"] = []
else:
    frappe.response["message"] = frappe.get_all(
        "User",
        filters={
            "name": ["in", user_names],
            "user_type": "System User",
            "enabled": 1
        },
        fields=["name", "full_name"],
        order_by="full_name asc",
        limit_page_length=0
    )

if not doc.custom_assign_project_user:
    roles = [d.role for d in frappe.db.get_all("Has Role", filters={"parent": frappe.session.user}, fields=["role"])]
    if "Projects Manager" in roles and "Project Admin" not in roles and "System Manager" not in roles:
        doc.custom_assign_project_user = frappe.session.user

if doc.has_value_changed("custom_assign_project_user") and doc.custom_assign_project_user:
    exists = frappe.db.exists(
        "ToDo",
        {
            "reference_type": doc.doctype,
            "reference_name": doc.name,
            "allocated_to": doc.custom_assign_project_user,
            "status": "Open"
        }
    )
    if not exists:
        try:
            todo = frappe.get_doc({
                "doctype": "ToDo",
                "reference_type": doc.doctype,
                "reference_name": doc.name,
                "allocated_to": doc.custom_assign_project_user,
                "description": "Project assigned via Manager form selector.",
                "status": "Open",
                "priority": "Medium"
            })
            todo.insert(ignore_permissions=True)
        except Exception:
            pass
